package pi_goal_x

// What the external test package (goal_rig_test.go, the real SDK through the fake host) needs from the package's internals: the
// original's tests reach `pi._goalCore` and the module functions directly; here that is the Probe. A slice that needs more adds its
// own export_<slice>_test.go with its own Probe methods; do not edit this file for it.

import (
	"encoding/json"
	"sort"
	"time"

	sdk "github.com/MichaelKinsy/PiG/extensions/sdk"
)

// RigAuditResult is a goalAuditorResult.
type RigAuditResult struct {
	Approved, Disapproved             bool
	Output, Model, ThinkingLevel, Err string
}

// RigDeps is goalDeps for the rig: the injected completion auditor sees the goal as JSON and the two summaries.
type RigDeps struct {
	Auditor func(goal map[string]any, detailedSummary, completionSummary string) RigAuditResult
}

// Probe is the core of a built extension.
type Probe struct{ c *core }

// NewGoalExtensionForTest is newGoalExtension that also returns the core (the original's `pi._goalCore`).
func NewGoalExtensionForTest(d RigDeps) (*sdk.Extension, *Probe) {
	deps := goalDeps{}
	if d.Auditor != nil {
		deps.runCompletionAuditor = func(a runGoalCompletionAuditorArgs) goalAuditorResult {
			r := d.Auditor(jsObjectMap(a.goal), a.detailedSummary, a.completionSummary)
			return goalAuditorResult{approved: r.Approved, disapproved: r.Disapproved, output: r.Output, model: r.Model, thinkingLevel: r.ThinkingLevel, err: r.Err}
		}
	}
	e, c := buildGoalExtension(deps)
	if c == nil {
		return e, nil
	}
	return e, &Probe{c: c}
}

// jsObjectMap is the object as plain decoded JSON (nil for nil).
func jsObjectMap(o *jsObject) map[string]any {
	if o == nil {
		return nil
	}
	var m map[string]any
	_ = json.Unmarshal([]byte(marshalJSON(o, "")), &m)
	return m
}

// Goal is core.state.goal as decoded JSON (nil when nothing is focused).
func (p *Probe) Goal() map[string]any {
	var out map[string]any
	p.c.locked(func() { out = jsObjectMap(p.c.state()) })
	return out
}

// GoalIDs are the ids of core.goalsById, sorted.
func (p *Probe) GoalIDs() []string {
	var ids []string
	p.c.locked(func() {
		for _, g := range p.c.goals.values() {
			ids = append(ids, gstr(g, "id"))
		}
	})
	sort.Strings(ids)
	return ids
}

func (p *Probe) FocusedGoalID() string {
	var id string
	p.c.locked(func() {
		if p.c.focused != nil {
			id = *p.c.focused
		}
	})
	return id
}

func (p *Probe) FocusRevision() int {
	var n int
	p.c.locked(func() { n = p.c.focusRev })
	return n
}

func (p *Probe) GoalModalDepth() int {
	var n int
	p.c.locked(func() { n = p.c.goalModalDepth })
	return n
}

// WidgetTap observes every widget push the SDK host forwards.
func (p *Probe) WidgetTap(fn func(key string, lines []string)) { p.c.widgetPushTap = fn }

// Locked runs fn as one unit of work against the core's current host (the last request's context).
func (p *Probe) Locked(fn func()) { p.c.locked(fn) }

// Scheduler operations, each one unit of work (the original's `core.scheduler.*(ctx)`).
func (p *Probe) SchedulerBegin()          { p.c.locked(p.c.scheduler.begin) }
func (p *Probe) SchedulerTurn()           { p.c.locked(p.c.scheduler.turn) }
func (p *Probe) SchedulerSettled(ok bool) { p.c.locked(func() { p.c.scheduler.settled(ok) }) }
func (p *Probe) SchedulerTakeover()       { p.c.locked(p.c.scheduler.takeover) }
func (p *Probe) SchedulerSchedule()       { p.c.locked(p.c.scheduler.schedule) }
func (p *Probe) SchedulerRestore()        { p.c.locked(p.c.scheduler.restore) }
func (p *Probe) SchedulerRecover()        { p.c.locked(p.c.scheduler.recover) }
func (p *Probe) SchedulerFailedDispatch() { p.c.locked(p.c.scheduler.failedDispatch) }
func (p *Probe) SchedulerResume() (ok bool) {
	p.c.locked(func() { ok = p.c.scheduler.resume() })
	return ok
}

// RigDeclare is a scheduler declaration's result.
type RigDeclare struct {
	Text      string
	Terminate bool
	Details   map[string]any
}

// SchedulerAttach is scheduler.attach (the wake listener).
func (p *Probe) SchedulerAttach() { p.c.locked(p.c.scheduler.attach) }

// SchedulerDeclareReady and SchedulerDeclareWait are scheduler.declare(ctx, {kind: ...}).
func (p *Probe) SchedulerDeclareReady() RigDeclare {
	return p.declare(goalContinuation{kind: "ready"})
}

func (p *Probe) SchedulerDeclareWait(reason, deadline, waitID string, intervalSeconds, maxChecks float64) RigDeclare {
	in := goalContinuation{kind: "wait", reason: &reason, deadline: deadline, waitID: waitID}
	if maxChecks != 0 {
		in.polling = &goalPolling{intervalSeconds, maxChecks}
	}
	return p.declare(in)
}

func (p *Probe) declare(in goalContinuation) (out RigDeclare) {
	p.c.locked(func() {
		r := p.c.scheduler.declare(in)
		out = RigDeclare{Text: r.text, Terminate: r.terminate, Details: jsObjectMap(r.details)}
	})
	return out
}

func (p *Probe) SchedulerMessage(message map[string]any) {
	p.c.locked(func() { p.c.scheduler.message(message) })
}

// FakeClock is mock timers over `Date.now` and the core's timers: nothing fires until Tick moves time across its due time.
type FakeClock struct {
	now      int64
	timers   []*fakeTimer
	oldNow   func() int64
	core     *core
	oldAfter func(time.Duration, func()) *time.Timer
}

type fakeTimer struct {
	due  int64
	fn   func()
	real *time.Timer
}

// FakeClock starts mock timers at startMs; Restore (also registered by the rig) puts the real clock back.
func (p *Probe) FakeClock(startMs int64) *FakeClock {
	f := &FakeClock{now: startMs, oldNow: clockMs, core: p.c, oldAfter: p.c.afterBase}
	clockMs = func() int64 { return f.now }
	p.c.afterBase = f.after
	return f
}

// after is the fake time.AfterFunc: the timer handed back is a real one that never fires. Stop on it is how the core cancels, and
// Tick asks it.
func (f *FakeClock) after(d time.Duration, fn func()) *time.Timer {
	t := &fakeTimer{due: f.now + d.Milliseconds(), fn: fn, real: time.NewTimer(24 * time.Hour)}
	f.timers = append(f.timers, t)
	return t.real
}

// Attach puts another core on this clock (the original's mock timers are global to the test).
func (f *FakeClock) Attach(p *Probe) { p.c.afterBase = f.after }

func (f *FakeClock) Now() int64 { return f.now }

// Tick advances time by ms, running every timer that became due, in due order.
func (f *FakeClock) Tick(ms int64) {
	end := f.now + ms
	for {
		sort.SliceStable(f.timers, func(i, j int) bool { return f.timers[i].due < f.timers[j].due })
		var next *fakeTimer
		idx := -1
		for i, t := range f.timers {
			if t.due <= end {
				next, idx = t, i
				break
			}
		}
		if next == nil {
			break
		}
		f.timers = append(f.timers[:idx], f.timers[idx+1:]...)
		if next.due > f.now {
			f.now = next.due
		}
		if next.real.Stop() { // false: the core cancelled it
			next.fn()
		}
	}
	f.now = end
}

// Restore puts the real clock and timers back.
func (f *FakeClock) Restore() {
	clockMs = f.oldNow
	f.core.afterBase = f.oldAfter
}
